      if (x0 !== x0) return NaN;
      const neg = x0 < 0; let x = neg ? -x0 : x0, id;
      if (x >= 7.378697629483821e19) return neg ? -(ATANHI[3] + ATANLO[3]) : ATANHI[3] + ATANLO[3];
