      const f = m - 1, s = f / (2 + f), z = s * s, w = z * z;
      const R = z * (LG1 + w * (LG3 + w * (LG5 + w * LG7))) + w * (LG2 + w * (LG4 + w * LG6));
      const hfsq = 0.5 * f * f;
