  function prepMoves(set) {
    for (const m of Object.values(set)) {
      let prev = { ...(m.air ? BASE_A : BASE_G) };
      m.keys = m.pose.map(([f, p]) => { prev = { ...prev, ...p }; return [f, prev]; });
    }
    return set;
  }
