    for (let k = 0; k < 5; k++) { const p = add(flower, new T.SphereGeometry(0.035, 8, 6), M(0xff3a6a), Math.cos(k * 1.256) * 0.035, Math.sin(k * 1.256) * 0.035, 0, false); p.scale.set(1, 1, 0.4); }
    add(flower, new T.SphereGeometry(0.016, 6, 4), M(0xffd23a), 0, 0, 0.01, false);

    // Bras fins, bracelets dorés, ongles vernis
