      add(arm, new T.CylinderGeometry(0.05, 0.042, 0.28, 10), mSkin, 0, -0.45, 0);
      add(arm, new T.TorusGeometry(0.048, 0.009, 6, 14), mGold, 0, -0.56, 0, false).rotation.x = Math.PI / 2;
      add(arm, new T.SphereGeometry(0.05, 10, 8), mSkin, 0, -0.62, 0);
