    const dark = new T.MeshBasicMaterial({ color: 0x14101c });

    // Pantalon de velours remonté haut, charentaises
    add(hips, new T.CylinderGeometry(0.31, 0.3, 0.2, 16), mPants, 0, -0.04, 0);
    const legs = [];
