      const leg = new T.Group(); leg.position.set(0, 0, z); hips.add(leg);
      add(leg, new T.CylinderGeometry(0.145, 0.125, 0.48, 12), mPants, 0, -0.25, 0);
      add(leg, new T.CylinderGeometry(0.125, 0.12, 0.3, 12), mPants, 0, -0.62, 0);
      for (let k = 0; k < 4; k++) add(leg, new T.BoxGeometry(0.005, 0.7, 0.012), mPantsD, 0.13, -0.4, (k - 1.5) * 0.05, false);   // côtes du velours
      const sl = add(leg, new T.SphereGeometry(1, 14, 10), mSlip, 0.05, -0.83, 0); sl.scale.set(0.17, 0.075, 0.115);              // charentaises
      add(leg, new T.TorusGeometry(0.095, 0.02, 6, 14), M(0x3a2a2a), 0.02, -0.8, 0, false).rotation.x = Math.PI / 2;
