  const REL_FAKE = 0;                                                        // (tests) heure imposée
  let REL_CLOCK = () => REL_FAKE || Date.now();
  const isReleased = (id) => !(id in RELEASES) || REL_CLOCK() >= RELEASES[id];
  const releaseDate = (id) => { const t = RELEASES[id]; if (!t) return ''; const d = new Date(t + REL_TZ * 3600e3); return String(d.getUTCDate()).padStart(2, '0') + '/' + String(d.getUTCMonth() + 1).padStart(2, '0'); };
  const REL_SEEN_KEY = 'ssk-rel-seen-v1';
  const relSeen = () => { try { const v = JSON.parse(localStorage.getItem(REL_SEEN_KEY) || 'null'); return Array.isArray(v) ? v : null; } catch (e) { return null; } };
  const relMarkSeen = (id) => { const s = relSeen() || []; if (!s.includes(id)) { s.push(id); try { localStorage.setItem(REL_SEEN_KEY, JSON.stringify(s)); } catch (e) {} } };

  const isOwned = (id) => { if (!isReleased(id)) return false; if (!STORY_UNLOCKS.includes(id)) return true; try { return (JSON.parse(localStorage.getItem('ssk-unlocks-v1') || '[]') || []).includes(id); } catch (e) { return false; } };
