      box(2.2, 0.5, 3.0, std(0x2a2018, { roughness: 0.4 }), -9.0, 0.25, -6.5); solid(-10.1, -8.0, -7.9, -5.0);
      cyl(0.08, 0.08, 0.3, std(0xd8d8d8), -9.2, 0.65, -6.0); cyl(0.12, 0.12, 0.05, std(0x111111), -8.6, 0.53, -7.2);
      // poster du jeu sur le mur du sud
