      barNeon.rotation.y = -Math.PI / 2; barNeon.position.set(13.3, 4.55, -6.4); sc.add(barNeon);
      const tap = new T.Group(); tap.position.set(9.6, 1.23, -5.2); bar.add(tap);
      box(0.25, 0.6, 0.25, std(0xc0c0c8, { metalness: 0.9, roughness: 0.25 }), 0, 0.3, 0, tap); for (const z of [-0.12, 0.12]) box(0.05, 0.25, 0.05, std(0x111111), -0.12, 0.62, z, tap);
      for (let i = 0; i < 4; i++) { const gl = cyl(0.08, 0.07, 0.2, new T.MeshStandardMaterial({ color: 0xffffff, transparent: true, opacity: 0.35, roughness: 0.05 }), 9.5, 1.33, -8.6 + i * 0.3, 10, bar); }
      const barL = new T.PointLight(0xff4ab0, 1.0, 12, 2); barL.position.set(11.5, 3.6, -6.4); sc.add(barL);
      const barL2 = new T.PointLight(0xffb070, 0.7, 10, 2); barL2.position.set(8.5, 3.8, -6.4); sc.add(barL2);

      // ======== COIN FUMETTE (sud-ouest du salon) ========
      const chill = new T.Mesh(new T.CircleGeometry(3.2, 32), std(0x2a3a1e, { roughness: 1 })); chill.rotation.x = -Math.PI / 2; chill.position.set(-11, 0.012, 0.6); sc.add(chill);
      const beanCols = [0x7a3ab0, 0xe8b400, 0x2ea84a, 0xe8343a];
      [[-12.6, -0.8], [-9.4, -0.6], [-12.4, 2.6], [-9.6, 2.5]].forEach(([x, z], i) => {
        const b = new T.Mesh(new T.SphereGeometry(0.85, 18, 12), std(beanCols[i], { roughness: 1 })); b.scale.set(1, 0.55, 1); b.position.set(x, 0.42, z); sc.add(b); solid(x - 0.6, z - 0.6, x + 0.6, z + 0.6);
      });
      cyl(0.7, 0.7, 0.08, std(0x3a2a1a, { roughness: 0.4 }), -11, 0.45, 0.9); cyl(0.12, 0.2, 0.42, std(0x3a2a1a), -11, 0.2, 0.9); solid(-11.6, 0.3, -10.4, 1.5);
