      this.lavaBlobs = []; for (let i = 0; i < 3; i++) { const b = new T.Mesh(new T.SphereGeometry(0.07 + i * 0.015, 10, 8), new T.MeshBasicMaterial({ color: 0xc8ff5a })); lava.add(b); this.lavaBlobs.push(b); }
      const chillL = new T.PointLight(0x5aff7a, 0.9, 9, 2); chillL.position.set(-11.5, 2.2, 1); sc.add(chillL);
      const chillNeon = new T.Mesh(new T.PlaneGeometry(4.4, 1.1), new T.MeshBasicMaterial({ map: neonTex('COIN FUMETTE', '#5aff7a'), transparent: true, depthWrite: false }));
      chillNeon.rotation.y = Math.PI / 2; chillNeon.position.set(-13.8, 3.6, 0.8); sc.add(chillNeon);
