      const clubFloor = new T.Mesh(new T.PlaneGeometry(24, 20), std(0x0c0c14, { roughness: 0.35, metalness: 0.3 })); clubFloor.rotation.x = -Math.PI / 2; clubFloor.position.set(0, 0, 14); sc.add(clubFloor);
      const clubWall = std(0x0e0d1a, { roughness: 0.9 });
