      const mtx = new T.Matrix4(); let k = 0;
      for (let i = 0; i < NX; i++) for (let j = 0; j < NZ; j++) { mtx.makeTranslation(-6 + TS / 2 + i * TS, 0.03, 9.6 + TS / 2 + j * TS); tiles.setMatrixAt(k, mtx); tiles.setColorAt(k, new T.Color(0x222222)); k++; }
      sc.add(tiles); this.tileN = { NX, NZ };
      // cabine du DJ
