      box(6.4, 1.3, 1.6, std(0x15151f, { roughness: 0.3, metalness: 0.4 }), 0, 0.65, 0, dj); box(6.6, 0.08, 1.8, std(0x2a2a35, { metalness: 0.5, roughness: 0.25 }), 0, 1.33, 0, dj);
      box(6.42, 0.1, 1.62, new T.MeshBasicMaterial({ color: 0x5ad1ff }), 0, 0.15, 0, dj);
      this.decks = [-1.6, 1.6].map(x => { const d = cyl(0.42, 0.42, 0.05, std(0x111111, { roughness: 0.3 }), x, 1.4, 0, 24, dj); const lab = cyl(0.12, 0.12, 0.052, new T.MeshBasicMaterial({ color: x < 0 ? 0xff3ca0 : 0xffd979 }), 0, 0, 0, 16, d); lab.position.y = 0.002; return d; });
      box(0.8, 0.08, 0.5, std(0x333340, { metalness: 0.5 }), 0, 1.4, 0, dj);
      solid(-3.3, 21.3, 3.3, 23.2);
      const djNeon = new T.Mesh(new T.PlaneGeometry(8, 2), new T.MeshBasicMaterial({ map: neonTex('NNN CLUB', '#5ad1ff'), transparent: true, depthWrite: false })); djNeon.position.set(0, 4.0, 23.8); djNeon.rotation.y = Math.PI; sc.add(djNeon);
      // enceintes
