      if (this.mini) { ix = 0; iy = 0; }
      const mag = Math.min(1, Math.hypot(ix, iy));
      let moving = mag > 0.15 && m.a !== 'ko';
      if (moving && m.a === 'sit' && this.act !== 'poop') this.standUp();
      if (moving && this.act && this.act !== 'poop') { this.act = null; m.a = 'idle'; }
      if (m.a === 'dance' && !(m.x > -6.5 && m.x < 6.5 && m.z > 9 && m.z < 21)) m.a = moving ? 'walk' : 'idle';   // on danse aussi en marchant, tant qu'on reste sur la piste
