      el.querySelector('.sk-hub-m .bar b').style.width = m.h + '%';
      const cnt = this.remote.size + 1;
      const top = el.querySelector('.sk-hub-top span'); const txt = `· ${cnt} KHEY${cnt > 1 ? 'S' : ''} ICI`; if (top.textContent !== txt) top.textContent = txt;
      const who = [NET.name() + ' (toi)', ...[...this.remote.values()].map(a => a.name)].slice(0, 12).map(n => '• ' + esc(n)).join('<br>');
      const w = el.querySelector('.sk-hub-who'); if (w._h !== who) { w._h = who; w.innerHTML = who; }
      const bl = el.querySelector('.sk-hub-black');
