      const M = new T.Matrix4(), Q = new T.Quaternion(), E = new T.Euler(), V = new T.Vector3(), Sv = new T.Vector3();
      const put = (g, c, x, y, z, sx = 1, sy = 1, sz = 1, rx = 0, ry = 0, rz = 0) => { M.compose(V.set(x, y, z), Q.setFromEuler(E.set(rx, ry, rz)), Sv.set(sx, sy, sz)); parts.push({ g, c, m: M.clone() }); };
