        if (Math.abs(x - I.cx) > I.rx * 1.2) continue;
        if (this.pip(I, x, y, 0.835, 0.755, -8)) return MAP_TOP + MAP_GRASS;
        if (this.pip(I, x, y, 1.0, 1.0, 0)) return MAP_TOP;
