      for (const [x, y] of I.pts) { x0 = Math.min(x0, x); x1 = Math.max(x1, x); y0 = Math.min(y0, y); y1 = Math.max(y1, y); }
      x0 -= 20; x1 += 20; y0 -= 20; y1 += 20;
      const cw = 1600, ch = Math.round(cw * (y1 - y0) / (x1 - x0)), c = document.createElement('canvas'); c.width = cw; c.height = ch;
      const g = c.getContext('2d'), k = cw / (x1 - x0);
