      const polyT = (g, dx = 0, dy = 0, sx = 1, sy = 1) => { g.beginPath(); I.pts.forEach(([x, y], i) => { const X = I.cx + (x - I.cx) * sx + dx, Y = I.cy + (y - I.cy) * sy + dy; i ? g.lineTo(X, Y) : g.moveTo(X, Y); }); g.closePath(); };
