        g.strokeStyle = 'rgba(200,160,100,.35)'; g.lineWidth = 2;
        for (let n = 0; n < 220; n++) { const an = rnd() * TAU, f = 0.78 + rnd() * 0.2, x = I.cx + Math.cos(an) * I.rx * f, y = I.cy + Math.sin(an) * I.ry * f; g.beginPath(); g.arc(x, y, 6 + rnd() * 6, Math.PI * 1.1, Math.PI * 1.9); g.stroke(); }
        g.fillStyle = 'rgba(190,150,80,.35)'; for (let n = 0; n < 900; n++) { const an = rnd() * TAU, f = 0.75 + rnd() * 0.24; g.fillRect(I.cx + Math.cos(an) * I.rx * f, I.cy + Math.sin(an) * I.ry * f, 2.5, 2.5); }
