        g.globalAlpha = 1;
        for (let n = 0; n < 3000; n++) { const x = I.cx + (rnd() - 0.5) * I.rx * 1.8, y = I.cy + (rnd() - 0.5) * I.ry * 1.7; g.strokeStyle = rnd() < 0.55 ? 'rgba(20,90,20,.35)' : 'rgba(200,255,150,.4)'; g.lineWidth = 1.6; g.beginPath(); g.moveTo(x, y); g.lineTo(x + (rnd() - 0.5) * 4, y - 4 - rnd() * 5); g.stroke(); }
        for (let n = 0; n < 160; n++) { const x = I.cx + (rnd() - 0.5) * I.rx * 1.6, y = I.cy + (rnd() - 0.5) * I.ry * 1.5; g.fillStyle = ['#ffffff', '#ffe066', '#ff8ab0', '#8ad0ff'][n % 4]; for (let a = 0; a < 4; a++) { g.beginPath(); g.arc(x + Math.cos(a * 1.57) * 2.2, y + Math.sin(a * 1.57) * 2.2, 1.8, 0, TAU); g.fill(); } }
        if (I.k === 3) { g.fillStyle = 'rgba(90,60,30,.35)'; g.beginPath(); g.ellipse(I.cx, I.cy, I.rx * 0.3, I.ry * 0.3, 0, 0, TAU); g.fill(); }
