      if (S[other] && S[other].u === NET.uid) up[other] = null;
      if (S[other] && S[other].u !== NET.uid && this.present(S[other].u)) { up.ca = [1, 1, 1, 1, 1, 1]; up.cb = [1, 1, 1, 1, 1, 1]; up.turn = 'a'; }
