          const S = this.bp, side = ['a', 'b'].find(s => S[s] && S[s].u === NET.uid), opp = side === 'a' ? 'b' : 'a', dir = side === 'a' ? 1 : -1, oppEnd = side === 'a' ? BP.xb : BP.xa;
