    floor.position.set((layout.L + layout.R) / 2, layout.top - floorH / 2, 0); s.add(floor);
    const edge = new T.Mesh(new T.BoxGeometry(sw + 0.05, 0.07, floorD + 0.05), glowM(0x9146ff, 0.9)); edge.position.set(floor.position.x, layout.top - 0.02, 0); s.add(edge); A.edge = edge;
    // dessous : la scène « flotte » dans la page, avec un reflet violet
